```python
def flatten(nested):
    """Flatten a nested list of lists into a single list."""
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result


# Example
if __name__ == "__main__":
    print(flatten([1, [2, [3, 4], 5], 6, [7]]))
    # Output: [1, 2, 3, 4, 5, 6, 7]
```

